def build(baselines):
    result = copy.deepcopy(baselines)
    core = result['team5-web-response-core']['definition']['States']
    for name in ('EvaluateExistingIsolation', 'EvaluateVerification'):
        choice = core[name]['Choices'][0]
        assert choice['Next'] == 'ChooseRecovery'
        choice['Next'] = 'TagOriginalIsolated'
    add_tag(core, 'TagOriginalIsolated', SOURCE, 'isolated', 'ChooseRecovery', False)
    branch = result['team5-recovery-workflow']['definition']['States']['RunProxyRecovery']['Branches'][0]['States']
    assert branch['ExtractInstanceId']['Next'] == 'StartRdsRestore'
    branch['ExtractInstanceId']['Next'] = 'TagRecoveredPreparing'
    add_tag(branch, 'TagRecoveredPreparing', '$.Recovered.InstanceId', 'recovering', 'StartRdsRestore', True)
    choice = branch['VerifyListenerTarget']['Choices'][0]
    assert choice['Next'] == 'ServiceCutoverCompleted'
    choice['Next'] = 'TagRecoveredActive'
    add_tag(branch, 'TagRecoveredActive', '$.Recovered.InstanceId', 'active', 'ServiceCutoverCompleted', True)
    return result


def add_tag(states, name, instance, status, following, dynamic):
    assert name not in states
    warning = name + 'Warning'
    tags = [{'Key': 'RecoveryStatus', 'Value': status},
            {'Key': 'RecoverySourceInstanceId', 'Value': SOURCE},
            {'Key': 'RecoveryExecutionArn', 'Value.$': '$$.Execution.Id'},
            {'Key': 'RecoveryStatusUpdatedAt', 'Value.$': '$$.State.EnteredTime'}]
    params = {'Tags': tags}
    params['Resources.$' if dynamic else 'Resources'] = ('States.Array(' + instance + ')') if dynamic else [instance]
    states[name] = {
        'Type': 'Task', 'Resource': 'arn:aws:states:::aws-sdk:ec2:createTags',
        'Parameters': params, 'ResultPath': None, 'TimeoutSeconds': 30,
        'Retry': [{'ErrorEquals': ['States.TaskFailed'], 'IntervalSeconds': 2, 'MaxAttempts': 3, 'BackoffRate': 2}],
        'Catch': [{'ErrorEquals': ['States.ALL'], 'ResultPath': '$.' + name + 'Error', 'Next': warning}],
        'Next': following,
    }
    states[warning] = {'Type': 'Pass', 'Result': 'Tag write failed. Dashboard status may be stale; inspect execution history.',
                       'ResultPath': '$.' + name + 'Warning', 'Next': following}


def policy(original_only):
    return {'Version': '2012-10-17', 'Statement': [{
        'Effect': 'Allow', 'Action': 'ec2:CreateTags',
        'Resource': f'arn:aws:ec2:{REGION}:{ACCOUNT}:instance/' + (SOURCE if original_only else '*'),
        'Condition': {
            'ForAllValues:StringEquals': {'aws:TagKeys': ['RecoveryStatus', 'RecoverySourceInstanceId', 'RecoveryExecutionArn', 'RecoveryStatusUpdatedAt']},
            'StringEquals': {'aws:RequestTag/RecoverySourceInstanceId': SOURCE,
                             'aws:RequestTag/RecoveryStatus': ['isolated'] if original_only else ['recovering', 'active']}
        }
    }]}


def save(path, obj):
    path.write_text(json.dumps(obj, indent=2, ensure_ascii=False, default=str), encoding='utf-8')


def main():
    parser = argparse.ArgumentParser(description='웹 EC2 대시보드 태그 단계 배포. 실행 시작 없음.')
    parser.add_argument('mode', choices=['prepare', 'apply'])
    args = parser.parse_args()
    import boto3
    session = boto3.Session(region_name=REGION)
    if session.client('sts').get_caller_identity()['Account'] != ACCOUNT:
        raise RuntimeError('프로젝트 계정이 아닙니다.')
    sf, iam = session.client('stepfunctions'), session.client('iam')
    after = build(BASELINES)
    names = ['team5-recovery-workflow', 'team5-web-response-core']
    current = {}
    for name, base in BASELINES.items():
        arn = base['stateMachineArn']
        if sf.list_executions(stateMachineArn=arn, statusFilter='RUNNING', maxResults=1)['executions']:
            raise RuntimeError('실행 중인 워크플로우가 있습니다: ' + name)
        live = sf.describe_state_machine(stateMachineArn=arn)
        definition = json.loads(live['definition'])
        if live['roleArn'] != base['roleArn'] or definition not in (base['definition'], after[name]['definition']):
            raise RuntimeError('수집 후 다른 변경이 있습니다. 덮어쓰지 않습니다: ' + name)
        current[name] = definition
    for name in names:
        response = sf.validate_state_machine_definition(definition=json.dumps(after[name]['definition']), type='STANDARD')
        if response['result'] != 'OK':
            raise RuntimeError(json.dumps(response.get('diagnostics'), ensure_ascii=False))
    folder = Path.home() / 'team5-recovery' / ('dashboard-tags-' + datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
    folder.mkdir(parents=True)
    for name in BASELINES:
        save(folder / (name + '-before.json'), current[name])
        save(folder / (name + '-after.json'), after[name]['definition'])
    roles = {}
    for name in names:
        role = BASELINES[name]['roleArn'].rsplit('/', 1)[-1]
        desired = policy(name == 'team5-web-response-core')
        try:
            old = iam.get_role_policy(RoleName=role, PolicyName=POLICY)['PolicyDocument']
        except iam.exceptions.NoSuchEntityException:
            old = None
        if old is not None and old != desired:
            raise RuntimeError('동일 이름의 다른 정책이 있어 중단합니다: ' + role)
        roles[role] = (old, desired)
        save(folder / (role + '-policy-before.json'), old)
        save(folder / (role + '-policy-after.json'), desired)
    print('AWS 정의 검증 완료. 검토/백업 폴더:', folder)
    if args.mode == 'prepare':
        print('AWS 변경 없음. 배포: python3 ~/setup-dashboard-tags.py apply')
        return
    # Recheck all definitions immediately before writes. AWS API has no conditional update parameter.
    for name, expected in current.items():
        live = sf.describe_state_machine(stateMachineArn=BASELINES[name]['stateMachineArn'])
        if json.loads(live['definition']) != expected or live['roleArn'] != BASELINES[name]['roleArn']:
            raise RuntimeError('배포 준비 중 설정이 변경됐습니다: ' + name)
        if sf.list_executions(stateMachineArn=BASELINES[name]['stateMachineArn'], statusFilter='RUNNING', maxResults=1)['executions']:
            raise RuntimeError('작업 실행이 시작되어 배포를 중단합니다.')
    for role, (old, desired) in roles.items():
        if old is None:
            iam.put_role_policy(RoleName=role, PolicyName=POLICY, PolicyDocument=json.dumps(desired))
    progress = []
    for name in names:
        arn = BASELINES[name]['stateMachineArn']
        if current[name] != after[name]['definition']:
            live = sf.describe_state_machine(stateMachineArn=arn)
            if json.loads(live['definition']) != current[name] or live['roleArn'] != BASELINES[name]['roleArn']:
                raise RuntimeError('배포 중 외부 변경이 발견됐습니다. 백업 폴더 확인: ' + str(folder))
            sf.update_state_machine(stateMachineArn=arn, definition=json.dumps(after[name]['definition']))
        for attempt in range(20):
            live = sf.describe_state_machine(stateMachineArn=arn)
            if json.loads(live['definition']) == after[name]['definition']:
                break
            time.sleep(1)
        else:
            raise RuntimeError('배포 후 정의 일치 확인 실패: ' + name)
        progress.append(name)
        save(folder / 'applied.json', progress)
        print('배포/재조회 확인:', name)
    print('웹 EC2 태그 단계 배포 완료. 격리/복원/태그 실제 쓰기는 실행하지 않았습니다.')
    print('현재 EC2 태그 초기화, 실패/복귀 상태, 배스천 태그는 포함하지 않습니다.')
    print('백업 참조와 RDS 여유 문제는 별도로 남아 있습니다. 지금 execute를 실행하지 마세요.')
    print('WebCore는 CloudFormation 관리 리소스입니다. 향후 기존 스택을 재배포하면 태그 단계가 제거될 수 있습니다.')


if __name__ == '__main__':
    main()
